func (p *Parser) argument(name string) *Node {
	if p.Err != nil {
		return emptyRow()
	}
	t := p.peek()
	if !containsWord("identifier number symbol command text eqref { frac binom overset underset sqrt accent", t.Kind) {
		p.fail(t.Column, "missing argument for "+name)
		return emptyRow()
	}
	return p.nucleus()
}
	case "sqrt":
		var index *Node
		if p.peek().Kind == "symbol" && p.peek().Value == "[" {
			open := p.read()
			nodes := p.elements(false, true)
			if p.Err == nil {
				if p.peek().Kind != "symbol" || p.peek().Value != "]" {
					p.fail(open.Column, "missing ]")
				} else {
					p.read()
				}
			}
			index = collapse(nodes)
		}
		body := p.argument(`\sqrt`)
		if index != nil {
			n.Kind = "root"
			n.Items = []*Node{index, body}
		} else {
			n.Items = []*Node{body}
		}
		return n
	case "sqrt", "root":
		bodyNode := n.Items[len(n.Items)-1]
		body := t.typeset(bodyNode, script)
		var index *Box
		e, top := 0, 0
		if n.Kind == "root" {
			index = t.typeset(n.Items[0], true)
			e = max(0, index.W-1)
			top = max(0, index.H-body.H)
		}
		k := body.H
		out := newBox(e+k+1+body.W, k+1+top, body.B+1+top, n.Kind)
		out.draw(repeated("_", body.W), e+k+1, top)
		out.draw(`\`, e, k+top)
		for r := 1; r <= k; r++ {
			out.draw("/", e+k-r+1, r+top)
		}
		if index != nil {
			out.add(index, 0, k-index.H+top, "index: ")
			out.add(body, e+k+1, 1+top, "body: ")
		} else {
			out.add(body, e+k+1, 1+top, "")
		}
		return out
func newBox(w, h, b int, description string) *Box {
	return &Box{W: w, H: h, B: b, Description: description}
}
